<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<div x-data="{type:'local'}" class="space-y-6"><div><h1 class="text-3xl font-bold">Backups cifrados</h1><p class="text-slate-400">Respalda la base de datos localmente, por SFTP o en almacenamiento S3 compatible.</p></div><section class="bg-slate-900 border border-slate-800 rounded-xl p-5"><h2 class="text-xl font-bold">Nuevo destino</h2><form method="post" action="/backups/destinations" class="grid md:grid-cols-4 gap-3 mt-4"><?=$csrf->field()?><input required name="name" placeholder="Nombre del destino" class="bg-slate-800 p-2 rounded"><select name="type" x-model="type" class="bg-slate-800 p-2 rounded"><option value="local">Local</option><option value="sftp">SFTP</option><option value="s3">Cloud / S3</option></select><input type="number" min="1" max="3650" name="retention_days" value="30" class="bg-slate-800 p-2 rounded" title="Retención en días"><div x-show="type==='sftp'" class="md:col-span-4 grid md:grid-cols-4 gap-3"><input name="host" placeholder="Host SFTP" class="bg-slate-800 p-2 rounded"><input name="port" value="22" class="bg-slate-800 p-2 rounded"><input name="username" placeholder="Usuario" class="bg-slate-800 p-2 rounded"><input type="password" name="password" placeholder="Contraseña" class="bg-slate-800 p-2 rounded"><input name="path" value="/backups" class="md:col-span-4 bg-slate-800 p-2 rounded"></div><div x-show="type==='s3'" class="md:col-span-4 grid md:grid-cols-2 gap-3"><input name="endpoint" placeholder="https://s3.region.example.com" class="bg-slate-800 p-2 rounded"><input name="bucket" placeholder="Bucket" class="bg-slate-800 p-2 rounded"><input name="access_key" placeholder="Access key" class="bg-slate-800 p-2 rounded"><input type="password" name="secret_key" placeholder="Secret key" class="bg-slate-800 p-2 rounded"><input name="path" value="orionx" class="md:col-span-2 bg-slate-800 p-2 rounded"></div><button class="md:col-start-4 bg-cyan-700 p-2 rounded">Guardar destino</button></form></section><section class="grid md:grid-cols-3 gap-4"><?php foreach($destinations as $d):?><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><div class="flex justify-between"><h2 class="font-bold"><?=$e($d['name'])?></h2><span class="uppercase text-cyan-400"><?=$e($d['type'])?></span></div><div class="text-sm text-slate-400 mt-3">Retención <?=$d['retention_days']?> días · <?=$d['backups_count']?> backups</div><div class="text-xs text-slate-500">Último: <?=$e($d['last_backup_at']??'Nunca')?></div><form method="post" action="/backups/run" class="mt-4"><?=$csrf->field()?><input type="hidden" name="destination_id" value="<?=$d['id']?>"><button class="bg-emerald-700 px-4 py-2 rounded">Crear backup ahora</button></form></article><?php endforeach?></section><section><h2 class="text-xl font-bold mb-3">Historial</h2><div class="space-y-2"><?php foreach($runs as $r):?><article class="bg-slate-900 border border-slate-800 rounded p-3 flex justify-between"><div><strong><?=$e($r['destination_name'])?></strong> · <?=$e($r['filename']??'Preparando')?><div class="text-xs text-red-400"><?=$e($r['error_message']??'')?></div></div><div class="text-right"><span><?=$e($r['status'])?></span><div class="text-xs text-slate-500"><?=$r['size_bytes']?number_format($r['size_bytes']/1048576,1).' MB':''?> · <?=$e($r['created_at'])?></div></div></article><?php endforeach?></div></section></div>
